using System;using System.IO;using System.Linq;using System.Runtime.InteropServices;using System.Collections.Generic;using System.Reflection;using System.Web.Script.Serialization;using interop.ICApiIronCAD;
namespace RockPro{public static class LatchInProcess{
 static Dictionary<string,object> O(object x){return (Dictionary<string,object>)x;}static IZDoc D(object x){return x is IZDoc?(IZDoc)x:(IZDoc)Marshal.GetObjectForIUnknown(new IntPtr(Convert.ToInt64(x)));}
 public static int Run(string folder){var j=new JavaScriptSerializer{MaxJsonLength=64000000};var result=new Dictionary<string,object>();try{
  var q=O(j.DeserializeObject(File.ReadAllText(Path.Combine(folder,"request.json"))));if(System.Diagnostics.Process.GetCurrentProcess().Id!=Convert.ToInt32(q["expected_pid"]))throw new Exception("Host changed");dynamic legacy=Marshal.GetActiveObject("IronCAD.Application");var app=(IZBaseApp)legacy.ZIronCADApp;if(!app.ApiVersion.StartsWith("29."))throw new Exception("2027 required");var docs=((Array)app.GetAllOpenDocs()).Cast<object>().Select(D).ToArray();string output=(string)q["output"];var doc=docs.Single(d=>d.Name==output);var s=(IZSceneDoc)doc;var u=(IZSceneDocUtility)s;var manifest=O(j.DeserializeObject((string)s.GetTopElement().get_CustomPropMgr(false).GetValueByName("RockPro.MountCounts.v1")));if((string)manifest["contract"]!="rockpro-tv-counts-v3")throw new Exception("Expected prepared v3 copy");
  var mapper=AppDomain.CurrentDomain.GetAssemblies().Single(a=>a.GetType("RockPro.CAD.WallMountMapper")!=null).GetType("RockPro.CAD.WallMountMapper");double maxPoseError=0;var rows=new List<object>();foreach(var row in ((object[])manifest["portable_rows"]).Select(O)){
   int wall=(int)s.ParameterMgr.GetParameterByName((string)row["wall"]).Value,section=row.ContainsKey("section")?(int)s.ParameterMgr.GetParameterByName((string)row["section"]).Value:0,n=(int)s.ParameterMgr.GetParameterByName((string)row["count"]).Value;int active=0;var labels=new List<string>();
   object[] frameArgs={s,manifest,wall,section==0?1:section,section==0,0.0,0.0};var frame=(double[])mapper.GetMethod("Frame").Invoke(null,frameArgs);double center=s.ParameterMgr.GetParameterByName((string)row["center"]).Value*1000,spread=s.ParameterMgr.GetParameterByName((string)row["spread"]).Value*1000,v=s.ParameterMgr.GetParameterByName((string)row["vertical"]).Value*1000;
   var slots=(object[])row["roots"];for(int i=0;i<slots.Length;i++){var ids=(object[])slots[i];bool suppressed=u.GetElementById(Convert.ToInt32(ids[0])).GetStateStatus(eZElementState.Z_SUPPRESSED);if(suppressed!=(i>=n))throw new Exception("Autonomous count mismatch "+row["key"]);if(!suppressed)active++;foreach(var raw in ids){var e=u.GetElementById(Convert.ToInt32(raw));if(e.GetStateStatus(eZElementState.Z_SUPPRESSED)!=suppressed)throw new Exception("Latch half mismatch");if(!suppressed){var anchor=(double[])mapper.GetMethod("Anchor").Invoke(null,new object[]{frame,center+(n<=1?0:(-.5+(double)i/(n-1))*spread),v});var local=((Array)((object[])row["root_poses"])[Array.IndexOf(ids,raw)]).Cast<object>().Select(Convert.ToDouble).ToArray();var expected=(double[])mapper.GetMethod("Compose").Invoke(null,new object[]{local,anchor});var m=((IZSceneElement)e).GetTransformToGlobal();for(int k=0;k<16;k++)maxPoseError=Math.Max(maxPoseError,Math.Abs(m.GetValue(k/4,k%4)-expected[k])*(k>=12&&k<15?1000:1));}labels.Add(e.Name);}}
   var cuts=new List<object>();foreach(var bag in ((object[])row["bags"]).Select(O))foreach(var feature in ((object[])bag["features"]).Select(O)){
    bool expected=Convert.ToInt32(bag["wall"])==wall&&Convert.ToInt32(bag["section"])==section&&Convert.ToInt32(feature["slot"])<n;var e=u.GetElementById(Convert.ToInt32(feature["id"]));if(e.GetStateStatus(eZElementState.Z_SUPPRESSED)==expected)throw new Exception("Autonomous cut routing mismatch "+feature["id"]);if(expected)cuts.Add(new{id=feature["id"],owner=e.GetOwnerPart().Id});if(q.ContainsKey("save")&&(bool)q["save"]){e.SetDisplayFlag(false);((IZElement)((IZExtrudeFeature)e).CrossSection).SetDisplayFlag(false);}
   }rows.Add(new{key=row["key"],wall=wall,section=section,requested=n,active=active,cuts=cuts,labels=labels});
  }
  if(maxPoseError>.08)throw new Exception("Autonomous root placement mismatch: "+maxPoseError);result["max_pose_error_mm"]=maxPoseError;if(q.ContainsKey("save")&&(bool)q["save"]){foreach(var parameter in Enumerable.Range(0,s.ParameterMgr.Count).Select(i=>s.ParameterMgr.GetParameter(i))){string name=parameter.Name;if((name.Contains("Lewa")||name.Contains("Prawa"))&&(name.StartsWith("RP_Uchwyt")||name.StartsWith("RP_Zamki"))){string key=name.StartsWith("RP_Zamki")?(name.Contains("Lewa")?"ZamkiA":"ZamkiB"):(name.Contains("Lewa")?(name.Contains("Czapka")?"UchwytyB":"UchwytyA"):(name.Contains("Czapka")?"UchwytyD":"UchwytyC"));if(!parameter.Notes.StartsWith("HISTORYCZNE",StringComparison.Ordinal))parameter.Notes="HISTORYCZNE — w R005 steruj rzędem przez RP_"+key+"_*. "+parameter.Notes;}}}
result["rows"]=rows;result["parameters"]=Enumerable.Range(0,s.ParameterMgr.Count).Select(i=>s.ParameterMgr.GetParameter(i)).Select(p=>new{name=p.Name,expression=p.Expression,value=p.Type==eZParamType.Z_PARAMETER_TYPE_TEXT?0:p.Value,notes=p.Notes}).ToArray();result["status"]=s.ParameterMgr.GetParameterByName("RP_IloscOkuc_Status").TextParameterValue;result["manual_apply_calls"]=0;result["manual_start_calls"]=0;
  result["controllers"]=AppDomain.CurrentDomain.GetAssemblies().Where(a=>a.GetType("RockPro.CAD.MountCountController")!=null).Select(a=>a.FullName).ToArray();
  if(q.ContainsKey("save")&&(bool)q["save"]){s.SaveAs(output,eZLinksSaveOptions.Z_LINKS_COPY_ALL,false);var camera=(IZCamera)s.CameraMgr.ActiveCamera;camera.Perspective=false;camera.Direction=new double[]{.65,.85,-.5};camera.Up=new double[]{0,0,1};s.AdjustCameraToFitShapeInRect(1500,1100);s.Redraw();s.ExportImage(Path.Combine(folder,"final.png"),eZImageFormat.Z_IMAGE_PNG,1500,1100,true);s.SaveAs(output,eZLinksSaveOptions.Z_LINKS_COPY_ALL,false);}
  if(q.ContainsKey("restart")&&(bool)q["restart"]){
   string original=(string)q["original"];if(docs.Any(d=>d.Name!=output&&d.Name!=original))throw new Exception("Unexpected document: no restart");if(File.Exists((string)q["snapshot"]))throw new Exception("Snapshot exists");s.SaveAsCopy((string)q["snapshot"],eZLinksSaveOptions.Z_LINKS_COPY_ALL,false);
   var old=docs.SingleOrDefault(d=>d.Name==original);if(old!=null){string path=(string)q["original_snapshot"];if(File.Exists(path))throw new Exception("Original snapshot exists");((IZSceneDoc)old).SaveAsCopy(path,eZLinksSaveOptions.Z_LINKS_COPY_ALL,false);}
   foreach(var assembly in AppDomain.CurrentDomain.GetAssemblies()){var type=assembly.GetType("RockPro.CAD.MountCountController");if(type!=null)type.GetMethod("Stop").Invoke(null,null);}foreach(var d in docs)d.Close2(true);var remaining=app.GetAllOpenDocs() as Array;if(remaining!=null&&remaining.Length!=0)throw new Exception("Some documents remain open");result["remaining_documents"]=0;
  }
  result["passed"]=true;
 }catch(Exception ex){result["passed"]=false;result["error"]=ex.ToString();}File.WriteAllText(Path.Combine(folder,"result.json"),j.Serialize(result));return (bool)result["passed"]?0:1;
 }
}}
